db = SQLDatabase.from_uri("sqlite:///resources/Chinook.db")


@tool
def query_playlist_db(query: str) -> str:
    """Query the database for playlist information"""
    try:
        return db.run(query)
    except Exception as e:
        return f"Error querying database: {e}"
